CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_read_own ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text NOT NULL DEFAULT '', preferences jsonb NOT NULL DEFAULT '{}');
GRANT SELECT,INSERT,UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_user_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id) ON CONFLICT DO NOTHING; RETURN NEW; END $$;
CREATE TRIGGER create_user_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_user_profile();
CREATE TABLE public.products (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200), reference text NOT NULL UNIQUE CHECK(length(reference) BETWEEN 1 AND 120), category text NOT NULL, specs text NOT NULL DEFAULT '', brand text NOT NULL DEFAULT '', usage text NOT NULL DEFAULT '', image_path text NOT NULL DEFAULT '', price numeric(12,2) NOT NULL CHECK(price>=0), old_price numeric(12,2) CHECK(old_price>price), availability text NOT NULL DEFAULT 'En stock' CHECK(availability IN ('En stock','Sur commande','Rupture de stock')), hidden boolean NOT NULL DEFAULT false, indicative boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.products TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.products TO authenticated;
GRANT ALL ON public.products TO service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY products_public ON public.products FOR SELECT TO anon,authenticated USING(NOT hidden);
CREATE POLICY products_admin ON public.products FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
ALTER TABLE public.quote_requests ADD COLUMN is_read boolean NOT NULL DEFAULT false;
GRANT SELECT,UPDATE,DELETE ON public.quote_requests TO authenticated;
GRANT ALL ON public.quote_requests TO service_role;
CREATE POLICY quotes_admin ON public.quote_requests FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.admin_content (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL CHECK(kind IN ('banner','review','newsletter','email')), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200), body text NOT NULL DEFAULT '', image_path text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.admin_content TO authenticated;
GRANT ALL ON public.admin_content TO service_role;
ALTER TABLE public.admin_content ENABLE ROW LEVEL SECURITY;
CREATE POLICY content_admin ON public.admin_content FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.store_settings (id text PRIMARY KEY DEFAULT 'store', data jsonb NOT NULL DEFAULT '{}');
GRANT SELECT,INSERT,UPDATE ON public.store_settings TO authenticated;
GRANT ALL ON public.store_settings TO service_role;
ALTER TABLE public.store_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY settings_admin ON public.store_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY image_admin_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='catalogue-images' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY image_admin_select ON storage.objects FOR SELECT TO authenticated USING(bucket_id='catalogue-images' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY image_admin_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='catalogue-images' AND public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.save_product_batch(rows jsonb) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; INSERT INTO public.products(id,name,reference,category,specs,brand,usage,image_path,price,old_price,availability,hidden,indicative) SELECT p.id,p.name,p.reference,p.category,p.specs,p.brand,p.usage,p.image_path,p.price,p.old_price,p.availability,p.hidden,p.indicative FROM jsonb_populate_recordset(NULL::public.products,rows) p ON CONFLICT(reference) DO UPDATE SET name=EXCLUDED.name,category=EXCLUDED.category,specs=EXCLUDED.specs,brand=EXCLUDED.brand,usage=EXCLUDED.usage,image_path=EXCLUDED.image_path,price=EXCLUDED.price,old_price=EXCLUDED.old_price,availability=EXCLUDED.availability,hidden=EXCLUDED.hidden,indicative=EXCLUDED.indicative; END $$;
REVOKE ALL ON FUNCTION public.save_product_batch(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_product_batch(jsonb) TO authenticated;